import sys
import weakref
from test import support

def simple_conjoin(gs):
    values = [None] * len(gs)

    def gen(i):
        if i >= len(gs):
            yield values
        else:
            for values[i] in gs[i]():
                for x in gen(i + 1):
                    yield x
    for x in gen(0):
        yield x

def conjoin(gs):
    n = len(gs)
    values = [None] * n

    def gen(i):
        if i >= n:
            yield values
        elif (n - i) % 3:
            ip1 = i + 1
            for values[i] in gs[i]():
                for x in gen(ip1):
                    yield x
        else:
            for x in _gen3(i):
                yield x

    def _gen3(i):
        assert i < n and (n - i) % 3 == 0
        ip1, ip2, ip3 = (i + 1, i + 2, i + 3)
        g, g1, g2 = gs[i:ip3]
        if ip3 >= n:
            for values[i] in g():
                for values[ip1] in g1():
                    for values[ip2] in g2():
                        yield values
        else:
            for values[i] in g():
                for values[ip1] in g1():
                    for values[ip2] in g2():
                        for x in _gen3(ip3):
                            yield x
    for x in gen(0):
        yield x

def flat_conjoin(gs):
    n = len(gs)
    values = [None] * n
    iters = [None] * n
    _StopIteration = StopIteration
    i = 0
    while 1:
        try:
            while i < n:
                it = iters[i] = gs[i]().__next__
                values[i] = it()
                i += 1
        except _StopIteration:
            pass
        else:
            assert i == n
            yield values
        i -= 1
        while i >= 0:
            try:
                values[i] = iters[i]()
                i += 1
                break
            except _StopIteration:
                i -= 1
        else:
            assert i < 0
            break

