        nonlocal frame
        try:
            yield
        finally:
            frame = sys._getframe()
    g = gen()
    wr = weakref.ref(g)
    next(g)
    del g
    support.gc_collect()
    assert wr() is None, ('assertIs', wr(), None)
    assert frame, ('assertTrue', frame)
    del frame
    support.gc_collect()
