def _t():
    old_garbage = gc.garbage[:]
    finalized = False

    def gen():
        nonlocal finalized
        try:
            g = (yield)
            yield 1
        finally:
            finalized = True
    g = gen()
    next(g)
    g.send(g)
    assert sys.getrefcount(g) >= 2, ('assertGreaterEqual', sys.getrefcount(g), 2)
    assert not finalized, ('assertFalse', finalized)
    del g
    support.gc_collect()
    assert finalized, ('assertTrue', finalized)
    assert gc.garbage == old_garbage, ('assertEqual', gc.garbage, old_garbage)
