        def remove_from_successors(i0, len=len):
            ne0 = ne1 = 0
            for i in succs[i0]:
                s = succs[i]
                s.remove(i0)
                e = len(s)
                if e == 0:
                    ne0 += 1
                elif e == 1:
                    ne1 += 1
            return ne0 == 0 and ne1 < 2

        def add_to_successors(i0):
            for i in succs[i0]:
                succs[i].append(i0)

