def simple_conjoin(gs):
    values = [None] * len(gs)

    def gen(i):
        if i >= len(gs):
            yield values
        else:
            for values[i] in gs[i]():
                for x in gen(i + 1):
                    yield x
    for x in gen(0):
        yield x

def conjoin(gs):
    n = len(gs)
    values = [None] * n

    def gen(i):
        if i >= n:
            yield values
        elif (n - i) % 3:
            ip1 = i + 1
            for values[i] in gs[i]():
                for x in gen(ip1):
                    yield x
        else:
            for x in _gen3(i):
                yield x

    def _gen3(i):
        assert i < n and (n - i) % 3 == 0
        ip1, ip2, ip3 = (i + 1, i + 2, i + 3)
        g, g1, g2 = gs[i:ip3]
        if ip3 >= n:
            for values[i] in g():
                for values[ip1] in g1():
                    for values[ip2] in g2():
                        yield values
        else:
            for values[i] in g():
                for values[ip1] in g1():
                    for values[ip2] in g2():
                        for x in _gen3(ip3):
                            yield x
    for x in gen(0):
        yield x

def flat_conjoin(gs):
    n = len(gs)
    values = [None] * n
    iters = [None] * n
    _StopIteration = StopIteration
    i = 0
    while 1:
        try:
            while i < n:
                it = iters[i] = gs[i]().__next__
                values[i] = it()
                i += 1
        except _StopIteration:
            pass
        else:
            assert i == n
            yield values
        i -= 1
        while i >= 0:
            try:
                values[i] = iters[i]()
                i += 1
                break
            except _StopIteration:
                i -= 1
        else:
            assert i < 0
            break

class Queens:

    def __init__(self, n):
        self.n = n
        rangen = range(n)
        self.rowgenerators = []
        for i in rangen:
            rowuses = [1 << j | 1 << n + i - j + n - 1 | 1 << n + 2 * n - 1 + i + j for j in rangen]

            def rowgen(rowuses=rowuses):
                for j in rangen:
                    uses = rowuses[j]
                    if uses & self.used == 0:
                        self.used |= uses
                        yield j
                        self.used &= ~uses
            self.rowgenerators.append(rowgen)

    def solve(self):
        self.used = 0
        for row2col in conjoin(self.rowgenerators):
            yield row2col

    def printsolution(self, row2col):
        n = self.n
        assert n == len(row2col)
        sep = '+' + '-+' * n
        print(sep)
        for i in range(n):
            squares = [' ' for j in range(n)]
            squares[row2col[i]] = 'Q'
            print('|' + '|'.join(squares) + '|')
            print(sep)

class Knights:

    def __init__(self, m, n, hard=0):
        self.m, self.n = (m, n)
        succs = self.succs = []

        def remove_from_successors(i0, len=len):
            ne0 = ne1 = 0
            for i in succs[i0]:
                s = succs[i]
                s.remove(i0)
                e = len(s)
                if e == 0:
                    ne0 += 1
                elif e == 1:
                    ne1 += 1
            return ne0 == 0 and ne1 < 2

        def add_to_successors(i0):
            for i in succs[i0]:
                succs[i].append(i0)

        def first():
            if m < 1 or n < 1:
                return
            corner = self.coords2index(0, 0)
            remove_from_successors(corner)
            self.lastij = corner
            yield corner
            add_to_successors(corner)

        def second():
            corner = self.coords2index(0, 0)
            assert self.lastij == corner
            if m < 3 or n < 3:
                return
            assert len(succs[corner]) == 2
            assert self.coords2index(1, 2) in succs[corner]
            assert self.coords2index(2, 1) in succs[corner]
            for i, j in ((1, 2), (2, 1)):
                this = self.coords2index(i, j)
                final = self.coords2index(3 - i, 3 - j)
                self.final = final
                remove_from_successors(this)
                succs[final].append(corner)
                self.lastij = this
                yield this
                succs[final].remove(corner)
                add_to_successors(this)

        def advance(len=len):
            candidates = []
            for i in succs[self.lastij]:
                e = len(succs[i])
                assert e > 0, 'else remove_from_successors() pruning flawed'
                if e == 1:
                    candidates = [(e, i)]
                    break
                candidates.append((e, i))
            else:
                candidates.sort()
            for e, i in candidates:
                if i != self.final:
                    if remove_from_successors(i):
                        self.lastij = i
                        yield i
                    add_to_successors(i)

        def advance_hard(vmid=(m - 1) / 2.0, hmid=(n - 1) / 2.0, len=len):
            candidates = []
            for i in succs[self.lastij]:
                e = len(succs[i])
                assert e > 0, 'else remove_from_successors() pruning flawed'
                if e == 1:
                    candidates = [(e, 0, i)]
                    break
                i1, j1 = self.index2coords(i)
                d = (i1 - vmid) ** 2 + (j1 - hmid) ** 2
                candidates.append((e, -d, i))
            else:
                candidates.sort()
            for e, d, i in candidates:
                if i != self.final:
                    if remove_from_successors(i):
                        self.lastij = i
                        yield i
                    add_to_successors(i)

        def last():
            assert self.final in succs[self.lastij]
            yield self.final
        if m * n < 4:
            self.squaregenerators = [first]
        else:
            self.squaregenerators = [first, second] + [hard and advance_hard or advance] * (m * n - 3) + [last]

    def coords2index(self, i, j):
        assert 0 <= i < self.m
        assert 0 <= j < self.n
        return i * self.n + j

    def index2coords(self, index):
        assert 0 <= index < self.m * self.n
        return divmod(index, self.n)

    def _init_board(self):
        succs = self.succs
        del succs[:]
        m, n = (self.m, self.n)
        c2i = self.coords2index
        offsets = [(1, 2), (2, 1), (2, -1), (1, -2), (-1, -2), (-2, -1), (-2, 1), (-1, 2)]
        rangen = range(n)
        for i in range(m):
            for j in rangen:
                s = [c2i(i + io, j + jo) for io, jo in offsets if 0 <= i + io < m and 0 <= j + jo < n]
                succs.append(s)

    def solve(self):
        self._init_board()
        for x in conjoin(self.squaregenerators):
            yield x

    def printsolution(self, x):
        m, n = (self.m, self.n)
        assert len(x) == m * n
        w = len(str(m * n))
        format = '%' + str(w) + 'd'
        squares = [[None] * n for i in range(m)]
        k = 1
        for i in x:
            i1, j1 = self.index2coords(i)
            squares[i1][j1] = format % k
            k += 1
        sep = '+' + ('-' * w + '+') * n
        print(sep)
        for i in range(m):
            row = squares[i]
            print('|' + '|'.join(row) + '|')
            print(sep)
_d_buf = []

def _d_print(*args, sep=' '):
    _d_buf.append(sep.join((str(a) for a in args)))

def _d_clear():
    _d_buf.clear()

def _d_ell_match(want, got):
    parts = want.split('...')
    if len(parts) == 1:
        return want == got
    if not got.startswith(parts[0]) or not got.endswith(parts[-1]):
        return False
    pos = len(parts[0])
    end = len(got) - len(parts[-1])
    for seg in parts[1:-1]:
        idx = got.find(seg, pos)
        if idx < 0 or idx > end:
            return False
        pos = idx + len(seg)
    return True

def _d_check(idx, want, ell=False):
    got = chr(10).join(_d_buf)
    ok = _d_ell_match(want, got) if ell else got == want
    if not ok and want in ('0', '1'):
        ok = got == ('False' if want == '0' else 'True')
    assert ok, ('doctest', idx, got, want)
